CREATE TABLE IF NOT EXISTS biz_his_bigdata (id bigint NOT NULL AUTO_INCREMENT, import_batch_no varchar(32) NOT NULL, patient_name varchar(50) NOT NULL, id_card varchar(32) NOT NULL, data_category varchar(50) DEFAULT NULL, data_json json DEFAULT NULL, create_by varchar(64) DEFAULT '', create_time datetime DEFAULT NULL, PRIMARY KEY (id), KEY idx_his_bd_batch (import_batch_no), KEY idx_his_bd_idcard (id_card), KEY idx_his_bd_name (patient_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
